// Task 4 row 227 (package X1-4; security review SX-09 (c); Known limit 30): THE RETAINED CERTIFICATE
// SET of the signer store - the certificates of every key that is or was the active one, each
// PARSED AND SELF-VERIFIED before it is listed. What is left out is named, never trusted, and never
// makes the read fail; a store that cannot be taken gives no set at all.
//
// SECRETS: every key is generated by this test in a temporary directory that `afterAll` removes
// and asserts gone. Nothing under the repository's data directory is named. Nothing is printed.
import { chmodSync, copyFileSync, lstatSync, mkdtempSync, readFileSync, readdirSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { ACTIVE_KEY_POINTER_NAME, SignerError, activateSigningKey, markSigningKeyCompromised, provisionSigningKey, readRetainedCertificates, readStoredCertificate, type RetainedCertificateSet } from '../index';

const NOW = 1_792_300_000_000;
const id = (place: number): string => `CORE-KEY-EVSIGN-${String(place).padStart(2, '0')}`;

const roots: string[] = [];
function store(): string {
  const root = mkdtempSync(join(realpathSync(tmpdir()), 'dems-row227-retained-'));
  roots.push(root);
  return join(root, 'signer');
}
afterAll(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
  for (const root of roots) expect(() => lstatSync(root)).toThrow();
});

const written: string[] = [];
beforeEach(() => {
  written.length = 0;
  const note = (...parts: unknown[]): boolean => {
    written.push(parts.map((part) => String(part)).join(' '));
    return true;
  };
  vi.spyOn(process.stdout, 'write').mockImplementation(note as never);
  vi.spyOn(process.stderr, 'write').mockImplementation(note as never);
  for (const level of ['log', 'info', 'warn', 'error', 'debug'] as const) vi.spyOn(console, level).mockImplementation(note as never);
});
afterEach(() => {
  vi.restoreAllMocks();
  expect(written).toEqual([]);
});

/** A store with keys 1..count, the last one active (each made active in turn, as rotations do). */
function rotatedStore(count: number): string {
  const dir = store();
  provisionSigningKey({ dir, now: NOW });
  for (let place = 2; place <= count; place += 1) {
    provisionSigningKey({ dir, now: NOW, keyId: id(place) });
    activateSigningKey({ dir, keyId: id(place), now: NOW });
  }
  return dir;
}

const shape = (set: RetainedCertificateSet) => ({ kept: set.certificates.map((entry) => `${entry.certificate.keyId}${entry.compromised ? ':COMPROMISED' : ''}`), refused: set.refused.map((entry) => `${entry.name}:${entry.reason}`) });
const codeOf = (run: () => unknown): string => {
  try {
    run();
    return 'NO_REFUSAL';
  } catch (error) {
    return error instanceof SignerError ? error.code : 'ANOTHER_ERROR';
  }
};

describe('row 227, SX-09 (c): the retained certificate set of the signer store', () => {
  it('no store: the empty set; one key: its certificate; after rotations: every key that was active, in the order of the series', () => {
    expect(shape(readRetainedCertificates({ dir: store() }))).toEqual({ kept: [], refused: [] });

    const one = store();
    const first = provisionSigningKey({ dir: one, now: NOW });
    const set = readRetainedCertificates({ dir: one });
    expect(shape(set)).toEqual({ kept: [id(1)], refused: [] });
    expect(set.certificates[0]?.certificate.sha256).toBe(first.sha256);
    expect(Object.isFrozen(set) && Object.isFrozen(set.certificates)).toBe(true);

    const dir = rotatedStore(3);
    const after = readRetainedCertificates({ dir });
    expect(shape(after)).toEqual({ kept: [id(1), id(2), id(3)], refused: [] });
    // Each is the certificate the store answers for that key id, and all three differ.
    for (const entry of after.certificates) expect(entry.certificate.sha256).toBe(readStoredCertificate({ dir, keyId: entry.certificate.keyId }).sha256);
    expect(new Set(after.certificates.map((entry) => entry.certificate.sha256)).size).toBe(3);
    // The read wrote nothing and changed nothing.
    const names = readdirSync(dir).sort();
    readRetainedCertificates({ dir });
    expect(readdirSync(dir).sort()).toEqual(names);
  });

  it('a key that was provisioned and NEVER active is left out (a rotation that stopped before the pointer moved)', () => {
    const dir = rotatedStore(2);
    provisionSigningKey({ dir, now: NOW, keyId: id(3) });
    expect(shape(readRetainedCertificates({ dir }))).toEqual({ kept: [id(1), id(2)], refused: [`${id(3)}:NEVER_ACTIVE`] });
    // Once it IS active it is in the set.
    activateSigningKey({ dir, keyId: id(3), now: NOW });
    expect(shape(readRetainedCertificates({ dir }))).toEqual({ kept: [id(1), id(2), id(3)], refused: [] });
    // A store without a pointer: only the first id was ever active.
    const fresh = store();
    provisionSigningKey({ dir: fresh, now: NOW });
    provisionSigningKey({ dir: fresh, now: NOW, keyId: id(2) });
    expect(shape(readRetainedCertificates({ dir: fresh }))).toEqual({ kept: [id(1)], refused: [`${id(2)}:NEVER_ACTIVE`] });
  });

  it('PARSED AND SELF-VERIFIED before it is listed: an edited certificate, a file that is none, a link, a file others can write, a foreign name - each left out by name, the rest kept', () => {
    const dir = rotatedStore(5);
    const crt = (place: number): string => join(dir, `${id(place)}.crt`);
    // 1: one character of the certificate body changed - it no longer parses or its self-signature fails.
    const pem = readFileSync(crt(1), 'utf8').split('\n');
    const line = pem[2] ?? '';
    pem[2] = `${line.slice(0, 10)}${line[10] === 'A' ? 'B' : 'A'}${line.slice(11)}`;
    chmodSync(crt(1), 0o644);
    writeFileSync(crt(1), pem.join('\n'));
    // 2: not a certificate at all.
    writeFileSync(crt(2), 'not a certificate\n');
    // 3: a link to a real certificate (of key 5).
    rmSync(crt(3));
    symlinkSync(crt(5), crt(3));
    // 4: a real certificate that the group can write.
    chmodSync(crt(4), 0o664);
    // A real, self-verifying certificate under a name that is no key id of the series.
    copyFileSync(crt(5), join(dir, 'FOREIGN-KEY-01.crt'));
    expect(shape(readRetainedCertificates({ dir }))).toEqual({
      kept: [id(5)],
      // In the order of the file names.
      refused: [`${id(1)}:CERTIFICATE_INVALID`, `${id(2)}:CERTIFICATE_INVALID`, `${id(3)}:CERTIFICATE_INVALID`, `${id(4)}:CERTIFICATE_INVALID`, 'FOREIGN-KEY-01:NOT_OF_THE_SERIES'],
    });
  });

  it('the compromise mark is stated per certificate; the certificate of a marked key stays in the set (it is needed to re-verify)', () => {
    const dir = rotatedStore(3);
    markSigningKeyCompromised({ dir, keyId: id(2), at: NOW + 1 });
    expect(shape(readRetainedCertificates({ dir }))).toEqual({ kept: [id(1), `${id(2)}:COMPROMISED`, id(3)], refused: [] });
    // A marked key whose key file is gone: still its certificate, still marked.
    rmSync(join(dir, `${id(2)}.p8`));
    rmSync(join(dir, `${id(2)}.wrap`));
    expect(shape(readRetainedCertificates({ dir })).kept).toEqual([id(1), `${id(2)}:COMPROMISED`, id(3)]);
  });

  it('a store that cannot be taken gives NO set: a pointer that cannot be read, a directory others can reach', () => {
    const dir = rotatedStore(2);
    const pointer = join(dir, ACTIVE_KEY_POINTER_NAME);
    chmodSync(pointer, 0o644);
    expect(codeOf(() => readRetainedCertificates({ dir }))).toBe('ACTIVE_KEY_POINTER_INVALID');
    chmodSync(pointer, 0o600);
    writeFileSync(pointer, 'CORE-KEY-EVSIGN-2\n');
    expect(codeOf(() => readRetainedCertificates({ dir }))).toBe('ACTIVE_KEY_POINTER_INVALID');
    writeFileSync(pointer, `${id(2)}\n`);
    expect(shape(readRetainedCertificates({ dir })).kept).toEqual([id(1), id(2)]);
    chmodSync(dir, 0o750);
    expect(codeOf(() => readRetainedCertificates({ dir }))).toBe('KEY_MODE');
    chmodSync(dir, 0o700);
    // A store of another user (stated, as row 210 does: one number, no replaceable stat).
    expect(codeOf(() => readRetainedCertificates({ dir, ownerUid: (process.getuid?.() ?? 0) + 1 }))).toBe('KEY_MODE');
  });
});
